     8→// Type represents a FreeLang type
     9→type Type interface {
    10→	String() string
    11→	TypeName() string
    12→}
    13→
    14→// BasicType represents primitive types
    15→type BasicType struct {
    16→	name string
    17→}
    18→
    19→func (bt *BasicType) String() string {
    20→	return bt.name
    21→}
    22→
    23→func (bt *BasicType) TypeName() string {
    24→	return bt.name
    25→}
    26→
    27→var (
    28→	// Primitive types
    29→	TypeInt    = &BasicType{"int"}
    30→	TypeFloat  = &BasicType{"float"}
    31→	TypeString = &BasicType{"string"}
    32→	TypeBool   = &BasicType{"bool"}
    33→	TypeNull   = &BasicType{"null"}
    34→	TypeVoid   = &BasicType{"void"}
    35→	TypeAny    = &BasicType{"any"}
    36→)
    37→
    38→// ArrayType represents an array type
    39→type ArrayType struct {
    40→	ElementType Type
    41→}
    42→
    43→func (at *ArrayType) String() string {
    44→	return fmt.Sprintf("[%s]", at.ElementType.String())
    45→}
    46→
    47→func (at *ArrayType) TypeName() string {
    48→	return "array"
    49→}
    50→
    51→func NewArrayType(elementType Type) *ArrayType {
    52→	return &ArrayType{ElementType: elementType}
    53→}
    54→
    55→// HashType represents a hash/object type
    56→type HashType struct {
    57→	KeyType   Type
    58→	ValueType Type
    59→}
    60→
    61→func (ht *HashType) String() string {
    62→	return fmt.Sprintf("{%s: %s}", ht.KeyType.String(), ht.ValueType.String())
    63→}
    64→
    65→func (ht *HashType) TypeName() string {
    66→	return "hash"
    67→}
    68→
    69→func NewHashType(keyType, valueType Type) *HashType {
    70→	return &HashType{
    71→		KeyType:   keyType,
    72→		ValueType: valueType,
    73→	}
    74→}
    75→
    76→// FunctionType represents a function type
    77→type FunctionType struct {
    78→	ParameterTypes []Type
    79→	ReturnType     Type
    80→}
    81→
    82→func (ft *FunctionType) String() string {
    83→	params := make([]string, len(ft.ParameterTypes))
    84→	for i, t := range ft.ParameterTypes {
    85→		params[i] = t.String()
    86→	}
    87→	return fmt.Sprintf("func(%s) %s", strings.Join(params, ", "), ft.ReturnType.String())
    88→}
    89→
    90→func (ft *FunctionType) TypeName() string {
    91→	return "function"
    92→}
    93→
    94→func NewFunctionType(paramTypes []Type, returnType Type) *FunctionType {
    95→	return &FunctionType{
    96→		ParameterTypes: paramTypes,
    97→		ReturnType:     returnType,
    98→	}
    99→}
