   101→// UnionType represents a union type (type1 | type2)
   102→type UnionType struct {
   103→	Types []Type
   104→}
   105→
   106→func (ut *UnionType) String() string {
   107→	typeStrs := make([]string, len(ut.Types))
   108→	for i, t := range ut.Types {
   109→		typeStrs[i] = t.String()
   110→	}
   111→	return strings.Join(typeStrs, " | ")
   112→}
   113→
   114→func (ut *UnionType) TypeName() string {
   115→	return "union"
   116→}
   117→
   118→func NewUnionType(types ...Type) *UnionType {
   119→	return &UnionType{Types: types}
   120→}
   121→
   122→// TypesEqual checks if two types are equal
   123→func TypesEqual(a, b Type) bool {
   124→	// Handle nil cases
   125→	if a == nil && b == nil {
   126→		return true
   127→	}
   128→	if a == nil || b == nil {
   129→		return false
   130→	}
   131→
   132→	// Handle basic types (same instance)
   133→	if aBasic, ok := a.(*BasicType); ok {
   134→		if bBasic, ok := b.(*BasicType); ok {
   135→			return aBasic.name == bBasic.name
   136→		}
   137→		return false
   138→	}
   139→
   140→	// Handle array types
   141→	if aArray, ok := a.(*ArrayType); ok {
   142→		if bArray, ok := b.(*ArrayType); ok {
   143→			return TypesEqual(aArray.ElementType, bArray.ElementType)
   144→		}
   145→		return false
   146→	}
   147→
   148→	// Handle hash types
   149→	if aHash, ok := a.(*HashType); ok {
   150→		if bHash, ok := b.(*HashType); ok {
   151→			return TypesEqual(aHash.KeyType, bHash.KeyType) &&
   152→				TypesEqual(aHash.ValueType, bHash.ValueType)
   153→		}
   154→		return false
   155→	}
   156→
   157→	// Handle function types
   158→	if aFunc, ok := a.(*FunctionType); ok {
   159→		if bFunc, ok := b.(*FunctionType); ok {
   160→			if len(aFunc.ParameterTypes) != len(bFunc.ParameterTypes) {
   161→				return false
   162→			}
   163→			for i, at := range aFunc.ParameterTypes {
   164→				if !TypesEqual(at, bFunc.ParameterTypes[i]) {
   165→					return false
   166→				}
   167→			}
   168→			return TypesEqual(aFunc.ReturnType, bFunc.ReturnType)
   169→		}
   170→		return false
   171→	}
   172→
   173→	return false
   174→}
   175→
   176→// IsCompatible checks if type a is compatible with type b
   177→func IsCompatible(a, b Type) bool {
   178→	if TypesEqual(a, b) {
   179→		return true
   180→	}
   181→
   182→	// Any type is compatible with anything
   183→	if aBasic, ok := a.(*BasicType); ok && aBasic.name == "any" {
   184→		return true
   185→	}
   186→	if bBasic, ok := b.(*BasicType); ok && bBasic.name == "any" {
   187→		return true
   188→	}
   189→
   190→	// Handle union types
   191→	if aUnion, ok := a.(*UnionType); ok {
   192→		for _, t := range aUnion.Types {
   193→			if IsCompatible(t, b) {
   194→				return true
   195→			}
   196→		}
   197→		return false
   198→	}
   199→
   200→	return false
   201→}
